# Generated by the start-bridge codemod for git; re-run it instead of editing.
"""Validate and preserve the git staging artifact; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.
"""
import importlib.util
import os
from pathlib import Path

PROFILE = os.environ.get("VITE_GIT_NATIVE_PROFILE", "staging")
if PROFILE not in ("staging", "production"):
    raise ValueError("Unknown git native profile")
WORKER = "tuturuuu-git" if PROFILE == "production" else "tuturuuu-git-vite-staging"
PUBLIC_FILES = (
    "robots.txt",
    "sitemap.xml",
)
# No staging abuse-guard Worker exists in source: every profile binds the
# shared guard, the only service binding a Git artifact may carry.
SERVICES = [
    {
        "binding": "ABUSE_GUARD",
        "service": "tuturuuu-abuse-guard",
        "entrypoint": "AbuseGuardEntrypoint",
    },
]
ABUSE_GUARD_FAMILIES = "proxy"


def load():
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("git_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": WORKER,
        "vars": {
            "TUTURUUU_NOINDEX": "0" if PROFILE == "production" else "1",
            "ABUSE_GUARD_FAMILIES": ABUSE_GUARD_FAMILIES,
        },
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": False,
        "preview_urls": False,
    }
    module.NORMALIZED_DEFAULTS = {
        **module.NORMALIZED_DEFAULTS,
        "topLevelName": WORKER,
        "services": SERVICES,
    }
    module.RECEIPT = "git-native-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    return module


def main():
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "GIT_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["GIT_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load().main()


if __name__ == "__main__":
    main()
